from .constants import PARAMETER_BOUNDS, TORSION_PARAMETERS


def build_parameters() -> list[dict[str, object]]:
    lower, upper = PARAMETER_BOUNDS
    return [
        {
            "name": spec["name"],
            "type": "continuous",
            "bounds": {"lower": lower, "upper": upper},
            "description": (
                f"1-butanol torsion {spec['label']} in degrees; "
                f"atoms={spec['atoms_1based']} (1-based indices)."
            ),
        }
        for spec in TORSION_PARAMETERS
    ]


def parameter_values_from_suggestion(
    suggestion: dict[str, object],
) -> dict[str, float]:
    raw_values = suggestion.get("parameter_values") or {}
    return {
        spec["name"]: float(raw_values[spec["name"]])
        for spec in TORSION_PARAMETERS
    }
"}

