{"path":"butanol_dihedral_campaign/reporting.py","content":"from __future__ import annotations

import json
from pathlib import Path
from typing import Any

from .constants import ATTEMPT_LEDGER_NAME, EVALUATED_CANDIDATES_NAME, OBJECTIVE_NAME


TERMINAL_LEDGER_EVENTS = {"attempt_succeeded", "attempt_failed", "attempt_recovered_failed"}


def ensure_artifact_dir(root: Path, campaign_id: str) -> Path:
    artifact_dir = root / campaign_id
    artifact_dir.mkdir(parents=True, exist_ok=True)
    return artifact_dir


def append_jsonl(path: Path, payload: dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("a", encoding="utf-8") as handle:
        handle.write(json.dumps(payload, sort_keys=True) + "\n")


def read_jsonl(path: Path) -> list[dict[str, Any]]:
    if not path.exists():
        return []
    records: list[dict[str, Any]] = []
    with path.open("r", encoding="utf-8") as handle:
        for line in handle:
            line = line.strip()
            if line:
                records.append(json.loads(line))
    return records


def attempt_ledger_path(artifact_dir: Path) -> Path:
    return artifact_dir / ATTEMPT_LEDGER_NAME


def evaluated_candidates_path(artifact_dir: Path) -> Path:
    return artifact_dir / EVALUATED_CANDIDATES_NAME


def count_attempts_used(artifact_dir: Path) -> int:
    return sum(
        1
        for record in read_jsonl(attempt_ledger_path(artifact_dir))
        if record.get("event") == "attempt_started"
    )


def suggestion_attempt_state(artifact_dir: Path) -> dict[str, dict[str, Any]]:
    state: dict[str, dict[str, Any]] = {}
    for record in read_jsonl(attempt_ledger_path(artifact_dir)):
        suggestion_id = record.get("suggestion_id")
        if suggestion_id:
            state[str(suggestion_id)] = record
    return state


def record_attempt_started(
    artifact_dir: Path,
    *,
    attempt_index: int,
    suggestion_id: str,
    parameter_values: dict[str, float],
    batch_id: str,
    run_id: str,
) -> None:
    append_jsonl(
        attempt_ledger_path(artifact_dir),
        {
            "event": "attempt_started",
            "attempt_index": attempt_index,
            "suggestion_id": suggestion_id,
            "parameter_values": parameter_values,
            "batch_id": batch_id,
            "run_id": run_id,
        },
    )


def record_attempt_success(
    artifact_dir: Path,
    *,
    attempt_index: int,
    suggestion_id: str,
    parameter_values: dict[str, float],
    energy_hartree: float,
) -> None:
    payload = {
        "event": "attempt_succeeded",
        "attempt_index": attempt_index,
        "suggestion_id": suggestion_id,
        "parameter_values": parameter_values,
        "objective_name": OBJECTIVE_NAME,
        "objective_value": energy_hartree,
        "status": "succeeded",
    }
    append_jsonl(attempt_ledger_path(artifact_dir), payload)
    append_jsonl(evaluated_candidates_path(artifact_dir), payload)


def record_attempt_failure(
    artifact_dir: Path,
    *,
    attempt_index: int,
    suggestion_id: str,
    parameter_values: dict[str, float],
    error: str,
    recovered: bool = False,
) -> None:
    event = "attempt_recovered_failed" if recovered else "attempt_failed"
    payload = {
        "event": event,
        "attempt_index": attempt_index,
        "suggestion_id": suggestion_id,
        "parameter_values": parameter_values,
        "objective_name": OBJECTIVE_NAME,
        "objective_value": None,
        "status": "failed",
        "error": error,
    }
    append_jsonl(attempt_ledger_path(artifact_dir), payload)
    append_jsonl(evaluated_candidates_path(artifact_dir), payload)


def best_result(artifact_dir: Path) -> dict[str, Any] | None:
    best: dict[str, Any] | None = None
    for record in read_jsonl(evaluated_candidates_path(artifact_dir)):
        if record.get("status") != "succeeded":
            continue
        if best is None or float(record["objective_value"]) < float(best["objective_value"]):
            best = record
    return best
"}

